1483	/**

1620	 * alloc_dma_rx_desc_resources - alloc RX resources.
1621	 * @priv: private structure
1622	 * Description: according to which descriptor can be used (extend or basic)
1623	 * this function allocates the resources for TX and RX paths. In case of
1624	 * reception, for example, it pre-allocated the RX socket buffer in order to
1625	 * allow zero-copy mechanism.
1626	 */
1627	static int alloc_dma_rx_desc_resources(struct stmmac_priv *priv)
1628	{
1629		u32 rx_count = priv->plat->rx_queues_to_use;
1630		int ret = -ENOMEM;
1631		u32 queue;
1632	
1633		/* RX queues buffers and DMA */
1634		for (queue = 0; queue < rx_count; queue++) {
1635			struct stmmac_rx_queue *rx_q = &priv->rx_queue[queue];
1636			struct page_pool_params pp_params = { 0 };
1637			unsigned int num_pages;
1638	
1639			rx_q->queue_index = queue;
1640			rx_q->priv_data = priv;
1641	
1642			pp_params.flags = PP_FLAG_DMA_MAP;
1643			pp_params.pool_size = priv->dma_rx_size;
1644			num_pages = DIV_ROUND_UP(priv->dma_buf_sz, PAGE_SIZE);
1645			pp_params.order = ilog2(num_pages);
1646			pp_params.nid = dev_to_node(priv->device);
1647			pp_params.dev = priv->device;
1648			pp_params.dma_dir = DMA_FROM_DEVICE;
1649	
1650			rx_q->page_pool = page_pool_create(&pp_params);
1651			if (IS_ERR(rx_q->page_pool)) {
1652				ret = PTR_ERR(rx_q->page_pool);
1653				rx_q->page_pool = NULL;
1654				goto err_dma;
1655			}
1656	
1657			rx_q->buf_pool = kcalloc(priv->dma_rx_size,
1658						 sizeof(*rx_q->buf_pool),
1659						 GFP_KERNEL);
1660			if (!rx_q->buf_pool)
1661				goto err_dma;
1662	
1663			if (priv->extend_desc) {
1664				rx_q->dma_erx = dma_alloc_coherent(priv->device,
1665								   priv->dma_rx_size *
1666								   sizeof(struct dma_extended_desc),
1667								   &rx_q->dma_rx_phy,
1668								   GFP_KERNEL);
1669				if (!rx_q->dma_erx)
1670					goto err_dma;
1671	
1672			} else {
1673				rx_q->dma_rx = dma_alloc_coherent(priv->device,
1674								  priv->dma_rx_size *
1675								  sizeof(struct dma_desc),
1676								  &rx_q->dma_rx_phy,
1677								  GFP_KERNEL);
1678				if (!rx_q->dma_rx)
1679					goto err_dma;
1680			}
1681		}
1682	
1683		return 0;
1684	
1685	err_dma:
1686		free_dma_rx_desc_resources(priv);
1687	
1688		return ret;
1689	}
